}
.skip-link:focus {
  transform: none;
}
.app-shell {
  max-width: 1440px;
  min-height: 100svh;
  margin: 0 auto;
  padding: 0 64px;
  display: flex;
  flex-direction: column;
}
.app-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 32px 0;
  border-bottom: 1px solid #1c1920;
}
.wordmark {
  display: inline-flex;
  align-items: baseline;
  gap: 7px;
  font-size: 29px;
  line-height: 1.1;
  font-weight: 750;
  letter-spacing: -1.7px;
  text-decoration: none;
}
.header-context {
  color: var(--muted);
  font-size: 13px;
}
main {
  width: min(100%, 800px);
  margin: 74px auto 48px;
  flex: 1;
}
.search-intro {
  margin-bottom: 30px;
}
h1 {
  font-size: clamp(28px, 3.1vw, 38px);
  line-height: 1.2;
  letter-spacing: -1.4px;
  font-weight: 600;
  margin: 0 0 13px;
}
.search-intro p {
  color: var(--muted);
  font-size: 15px;
  line-height: 1.7;
  margin: 0;
}
.search-field {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 0 22px;
  min-height: 74px;
  border: 1px solid #493553;
  border-radius: 10px;
  background: var(--surface);
  transition:
    border-color 120ms ease,
    box-shadow 120ms ease;
}
.search-field:focus-within {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px #a863d61c;
}
.search-icon {
  display: flex;
  color: var(--accent);
  flex: none;
}
.search-field input {
  appearance: none;
  background: transparent;
  color: var(--text);
  border: 0;
  outline: none;
  min-width: 0;
  width: 100%;
  padding: 21px 0;
  font-size: 18px;
  font-weight: 500;
  line-height: 1.6;
  caret-color: var(--accent);
}
.search-field input::-webkit-search-cancel-button {
  display: none;
}
.search-field input::placeholder {
  color: #9c929f;
  font-weight: 400;
}
.search-shortcut {
  flex: none;
  white-space: nowrap;
  font: inherit;
  font-size: 14px;
  color: var(--muted);
  border: 1px solid #453c4a;
  border-radius: 5px;
  min-width: 26px;
  padding: 2px 7px;
  text-align: center;
}
.clear-button {
  color: var(--muted);
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  padding: 0;
  flex: none;
  border: 0;
  border-radius: 5px;
  background: transparent;
}
.clear-button:hover {
  color: var(--text);
  background: #2a2130;
}
.search-help {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.6;
  min-height: 20px;
  margin: 12px 2px 0;
}
.results-region {
  margin-top: 30px;
  min-height: 342px;
}
.results-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  min-height: 28px;
  padding-bottom: 16px;
}
.results-heading h2 {
  color: var(--text);
  font-size: 13px;
  line-height: 1.5;
  font-weight: 500;
  margin: 0;
}
.results-heading > span {
  color: var(--muted);
  font-size: 12px;
}
.results-list,
.loading-rows {
  border-top: 1px solid var(--line);
}
.results-list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.entity-row {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr) auto;
  align-items: center;
  gap: 18px;
  padding: 21px 0;
  border-bottom: 1px solid var(--line);
}
.entity-icon {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
<script lang="ts">
  import { PUBLIC_APP_VERSION } from "$app/env/public";
  import LandingPage from "./LandingPage.svelte";
  import MethodologyPage from "./MethodologyPage.svelte";
  import { pagePresentation } from "./lib/page";
  import SearchPage from "./SearchPage.svelte";
  import EntityDetails from "./EntityDetails.svelte";
  import type { PageModel } from "./lib/page";
  let { model }: { model: PageModel } = $props();
  const presentation = $derived(pagePresentation[model.kind]);
</script>

<svelte:head>
  <title>{presentation.title}</title>
  <meta name="description" content={presentation.description} />
</svelte:head>
<a class="skip-link" href={`#${presentation.target}`}
  >Skip to {presentation.label}</a
>
<div class="app-shell">
  <header class="app-header">
    <a class="wordmark" href="/" aria-label="Exposed home">exposed</a>
    <span class="header-context">UK Parliament</span>
  </header>

  {#if model.kind === "landing"}
    <LandingPage />
  {:else if model.kind === "methodology"}
    <MethodologyPage />
  {:else if model.kind === "search"}
    <SearchPage {model} />
  {:else if model.kind === "detail"}
    <EntityDetails {model} />
  {/if}
  <footer class="app-footer">
    <span>Version {PUBLIC_APP_VERSION}</span>
    <a
      href="/methodology"
      aria-current={model.kind === "methodology" ? "page" : undefined}
      >Methodology</a
    >
    <a
      href="https://www.parliament.uk/site-information/copyright-parliament/open-parliament-licence/"
      target="_blank"
      rel="noreferrer">Open Parliament Licence</a
    >
  </footer>
</div>
<script lang="ts">
  import "@fontsource-variable/manrope";
  import "../styles.css";
  let { children } = $props();
</script>

{@render children()}

