import {createServer} from 'node:http';
import {execFile} from 'node:child_process';
const server=createServer((request,response)=>{
 if(request.method!=='GET'){response.writeHead(405).end();return;}
 execFile('docker',['exec','exposed-exposed-1','curl','--silent','--show-error','--max-time','20','--write-out','\n%{http_code}','http://127.0.0.1:6999'+request.url],{maxBuffer:16*1024*1024},(error,output)=>{
  if(error){response.writeHead(502).end('Preview API unavailable');return;}
  const boundary=output.lastIndexOf('\n');
  response.writeHead(Number(output.slice(boundary+1)),{'content-type':'application/json'}).end(output.slice(0,boundary));
 });
});
server.listen(6998,'127.0.0.1',()=>console.log('Read-only preview API proxy listening at http://127.0.0.1:6998'));
